import React from "react";
import {
  FaCode,
  FaAward,
  FaUsers,
  FaComments,
  FaLightbulb,
  FaCogs,
  FaUsersCog,
  FaClock,
  FaBrain,
  FaBriefcase
} from "react-icons/fa";

const Skills = () => {
  return (
    <section className="skills-page">

      {/* HEADER */}
      <div className="header">
        <h1>Skills & Expertise</h1>
        <p>Technical capabilities, certifications, and real-world experience</p>
      </div>

      {/* TOP SECTION */}
      <div className="top">

        {/* LEFT */}
        <div className="card">
          <h2><FaCode /> Technical Skills</h2>
          <div className="tags">
            <span>Java</span>
            <span>React.js</span>
            <span>Spring Boot</span>
            <span>MySQL</span>
            <span>HTML</span>
            <span>CSS</span>
            <span>JavaScript</span>
          </div>
        </div>

        {/* RIGHT */}
        <div className="card">
          <h2><FaAward /> Certifications</h2>
          <div className="list">
            <p>• Java – NPTEL</p>
            <p>• Data Science for Engineers – NPTEL</p>
            <p>• SQL – HackerRank</p>
            <p>• Python – SoloLearn</p>
          </div>
        </div>

      </div>

      {/* INTERNSHIP */}
      <div className="section">

        <h2 className="section-title">
          <FaBriefcase /> Internship Experience
        </h2>

        <div className="timeline">

          <div className="timeline-card">
            <span className="num">01</span>
            <h3>Full Stack Java Intern</h3>
            <h4>Retech Solutions</h4>
            <p>
              Developed Student Portal Management System using Spring Boot,
              REST APIs, backend logic, authentication, and database integration.
            </p>
          </div>

          <div className="timeline-card">
            <span className="num">02</span>
            <h3>Data Analytics Intern</h3>
            <h4>Retech Solutions</h4>
            <p>
              Built Power BI dashboards, cleaned datasets, and transformed raw data
              into meaningful insights for decision-making.
            </p>
          </div>

        </div>

      </div>

      {/* SOFT SKILLS */}
      <div className="soft">

        <h2>Soft Skills</h2>

        <div className="soft-grid">
          <span><FaUsers /> Teamwork</span>
          <span><FaComments /> Communication</span>
          <span><FaLightbulb /> Problem Solving</span>
          <span><FaCogs /> Adaptability</span>
          <span><FaBrain /> Creativity</span>
          <span><FaUsersCog /> Leadership</span>
          <span><FaClock /> Time Management</span>
        </div>

      </div>

      {/* STYLE */}
      <style>{`

        .skills-page{
          min-height:100vh;
          padding:40px 10%;
          font-family:"Poppins",sans-serif;
          background:#0f172a;
          color:white;
        }

        /* HEADER */
        .header{
          text-align:center;
          margin-bottom:40px;
        }

        .header h1{
          font-size:40px;
          color:#38BDF8;
        }

        .header p{
          color:#94a3b8;
        }

        /* TOP SECTION */
        .top{
          display:grid;
          grid-template-columns:1fr 1fr;
          gap:20px;
          margin-bottom:40px;
        }

        .card{
          background:rgba(255,255,255,0.04);
          border:1px solid rgba(56,189,248,0.2);
          padding:20px;
          border-radius:16px;
          transition:0.3s;
        }

        .card:hover{
          transform:translateY(-5px);
          border-color:#38BDF8;
          box-shadow:0 0 20px rgba(56,189,248,0.2);
        }

        .card h2{
          color:#38BDF8;
          margin-bottom:15px;
          display:flex;
          gap:8px;
          align-items:center;
        }

        .tags{
          display:flex;
          flex-wrap:wrap;
          gap:10px;
        }

        .tags span{
          padding:6px 12px;
          border-radius:20px;
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          font-size:13px;
          color:#cbd5e1;
        }

        .list p{
          color:#cbd5e1;
          margin:6px 0;
        }

        /* SECTION */
        .section{
          margin-bottom:40px;
        }

        .section-title{
          color:#38BDF8;
          margin-bottom:20px;
          display:flex;
          gap:10px;
          align-items:center;
        }

        /* TIMELINE (CLEAN CARDS ONLY) */
        .timeline{
          display:flex;
          flex-direction:column;
          gap:15px;
        }

        .timeline-card{
          position:relative;
          padding:18px;
          border-radius:14px;
          background:rgba(255,255,255,0.04);
          border:1px solid rgba(56,189,248,0.2);
          transition:0.3s;
        }

        .timeline-card:hover{
          transform:translateY(-4px);
          border-color:#38BDF8;
        }

        .num{
          position:absolute;
          top:10px;
          right:12px;
          color:#38BDF8;
          font-size:12px;
        }

        .timeline-card h3{
          color:#e2e8f0;
        }

        .timeline-card h4{
          color:#38BDF8;
          font-size:13px;
        }

        .timeline-card p{
          color:#cbd5e1;
        }

        /* SOFT SKILLS */
        .soft{
          text-align:center;
        }

        .soft h2{
          color:#38BDF8;
          margin-bottom:20px;
        }

        .soft-grid{
          display:flex;
          flex-wrap:wrap;
          justify-content:center;
          gap:10px;
        }

        .soft-grid span{
          padding:8px 14px;
          border-radius:20px;
          background:rgba(56,189,248,0.1);
          border:1px solid rgba(56,189,248,0.3);
          color:#cbd5e1;
          display:flex;
          gap:6px;
          align-items:center;
        }

        @media(max-width:900px){
          .top{
            grid-template-columns:1fr;
          }
        }

      `}</style>

    </section>
  );
};

export default Skills;
